package com.gomgomapps.math.core;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public class NamibiaPairedTablesTest {
 @Test public void indexedDomainChecksEveryPublicPairWithoutStoredKeys(){var l=GlobalCurriculum.limits("na-nied-primary-2024-v1",PairedNumberTables.FILL,6);assertEquals(2124,PairedNumberTables.count(l));for(String id:List.of(PairedNumberTables.FILL,PairedNumberTables.RULE))for(int i=0;i<2124;i++){Question q=PairedNumberTables.at(id,i,l);var v=PairedNumberTables.read(q);assertNotNull(v);q.answers=PairedNumberTables.describe(q)?new String[]{"poison","poison"}:new String[]{"poison","poison","poison","poison","poison"};q.expression="poison";List<String> answers=PairedNumberTables.describe(q)?List.of(v.delta()>0?"0":"1",""+Math.abs(v.delta())):List.of(""+(v.first()[4]+v.delta()),""+(v.first()[5]+v.delta()),""+(v.first()[6]+v.delta()),v.delta()>0?"0":"1",""+Math.abs(v.delta()));assertTrue(new Checker().check(q,List.of(),answers).correct());assertFalse(HelpPlan.forQuestion(q).canTransfer());assertEquals(PairedNumberTables.describe(q)?5:9,HelpPlan.forQuestion(q).size());}}
 @Test public void normalNaSixSuppliesHaveBothSignsAllOffsetsAndFreshSevenColumnTables(){var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();Generator g=new Generator(new Random(298));for(String id:List.of(PairedNumberTables.FILL,PairedNumberTables.RULE)){assertTrue(pack.inGrade(id,6));List<String> recent=new ArrayList<>();Set<Integer> deltas=new HashSet<>();for(int i=0;i<300;i++){Question q=g.next(id,recent,false,GlobalCurriculum.limits(pack.id,id,6));assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=PairedNumberTables.read(q);assertNotNull(v);deltas.add(v.delta());for(int j=0;j<7;j++){assertTrue(v.first()[j]>=0&&v.first()[j]<=100);assertTrue(v.first()[j]+v.delta()>=0&&v.first()[j]+v.delta()<=100);}}assertEquals(24,deltas.size());}}
 @Test public void pairedRuleIsNotSuccessiveDifferenceAndLearnerHelpDoesNotTransfer(){Question q=PairedNumberTables.make(PairedNumberTables.RULE,1,4);q.answers=new String[]{"poison","poison"};assertTrue(new Checker().check(q,List.of(),List.of("0","4")).correct());assertFalse(new Checker().check(q,List.of(),List.of("0","1")).correct());assertEquals(0,new Checker().check(q,List.of(),List.of("1","4")).index);assertEquals(1,new Checker().check(q,List.of(),List.of("0","5")).index);HelpPlan h=HelpPlan.forQuestion(q);List<String> input=List.of("1","5","4","0","4");for(int i=0;i<5;i++)assertTrue(h.step(i).accepts(input.get(i)));q=PairedNumberTables.make(PairedNumberTables.FILL,12,-12);h=HelpPlan.forQuestion(q);input=List.of("12","0","-12","1","4","5","6","1","12");for(int i=0;i<9;i++)assertTrue(h.step(i).accepts(input.get(i)));assertTrue(new Checker().check(q,List.of(),List.of("4","5","6","1","12")).correct());assertEquals(3,new Checker().check(q,List.of(),List.of("4","5","6","0","12")).index);assertEquals(4,new Checker().check(q,List.of(),List.of("4","5","6","1","1")).index);}
 @Test public void malformedRowsCannotFallBackAndDomesticSequenceContractsStaySeparate(){Question q=PairedNumberTables.make(PairedNumberTables.FILL,1,4);q.prompt=q.prompt.replace("5 | 6 | 7 | 8","5 | 6 | 9 | 8");assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("9","10","11")).status);for(String id:List.of(PairedNumberTables.FILL,PairedNumberTables.RULE))assertFalse(Curriculum.inCurriculum(Catalog.get(id),2022));Question seq=LinearSequenceDescription.create(1,4);assertTrue(new Checker().check(seq,List.of(),List.of("0","4")).correct());Question desc=PairedNumberTables.make(PairedNumberTables.RULE,12,-12);assertTrue(new Checker().check(desc,List.of(),List.of("1","12")).correct());assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(desc,List.of(),Arrays.asList(null,"12")).status);}
}
